//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$inicio = $values["fecha_inicio"];
$fin    = $values["fecha_fin"];

if (empty(trim($values["nombre"]))) {
    $message = "El nombre del periodo es obligatorio (ej: 2026-1).";
    return false;
}

if (!empty($inicio) && !empty($fin)) {
    if ($fin <= $inicio) {
        $message = "La fecha de finalización debe ser estrictamente posterior a la fecha de inicio.";
        return false;
    }
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
